#!/usr/bin/env node

import { build } from 'esbuild';
import { writeFileSync, mkdirSync, existsSync, readFileSync, statSync, readdirSync } from 'fs';
import { join, dirname, relative, extname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

class CSSBundler {
    constructor(basePath) {
        this.basePath = basePath;
        this.cssImports = new Map();
        this.cssContent = new Map();
        this.componentCSSMap = new Map();
    }

    // Находим все CSS файлы в проекте
    async findCSSFiles(dir) {
        const files = [];

        async function scanDirectory(currentDir) {
            const entries = readdirSync(currentDir, { withFileTypes: true });

            for (const entry of entries) {
                const fullPath = join(currentDir, entry.name);

                if (entry.isDirectory()) {
                    // Пропускаем node_modules и скрытые папки
                    if (!entry.name.includes('node_modules') && !entry.name.startsWith('.')) {
                        await scanDirectory(fullPath);
                    }
                } else if (entry.isFile() && extname(entry.name) === '.css') {
                    files.push(fullPath);
                }
            }
        }

        await scanDirectory(dir);
        return files;
    }

    // Обрабатываем CSS файлы и создаем карту компонентов
    async processCSSFiles(cssFiles) {
        for (const filePath of cssFiles) {
            const content = readFileSync(filePath, 'utf-8');
            const relativePath = relative(this.basePath, filePath);

            // Обрабатываем @import правила
            const processedContent = await this.processCSSImports(content, dirname(filePath));
            this.cssContent.set(relativePath, processedContent);

            // Определяем к какому компоненту относится CSS
            const componentName = this.extractComponentName(relativePath);
            if (componentName) {
                if (!this.componentCSSMap.has(componentName)) {
                    this.componentCSSMap.set(componentName, []);
                }
                this.componentCSSMap.get(componentName).push(relativePath);
            }
        }
    }

    // Извлекаем имя компонента из пути к CSS
    extractComponentName(cssPath) {
        const match = cssPath.match(/components\/([^\/]+)\/css\//);
        return match ? match[1] : null;
    }

    // Обрабатываем @import в CSS
    async processCSSImports(content, baseDir) {
        const importRegex = /@import\s+(?:url\()?['"]([^'"]+)['"](?:\))?\s*;/g;
        let processedContent = content;

        let match;
        while ((match = importRegex.exec(content)) !== null) {
            const importPath = match[1];
            const fullImportPath = join(baseDir, importPath);

            if (existsSync(fullImportPath)) {
                const importedContent = readFileSync(fullImportPath, 'utf-8');
                const nestedContent = await this.processCSSImports(importedContent, dirname(fullImportPath));
                processedContent = processedContent.replace(match[0], nestedContent);
            }
        }

        return processedContent;
    }

    // Генерируем единый CSS бандл
    generateCSSBundle() {
        let bundle = '/* CSS Bundle - Generated by esbuild */\n';

        for (const [filePath, content] of this.cssContent) {
            bundle += `\n/* ${filePath} */\n`;
            bundle += content;
            bundle += '\n';
        }

        return bundle;
    }

    // Создаем виртуальный модуль для CSS
    createCSSModule() {
        const cssBundle = this.generateCSSBundle();
        const cssPaths = Array.from(this.cssContent.keys());

        return `
      const cssContent = ${JSON.stringify(cssBundle)};
      const cssPaths = ${JSON.stringify(cssPaths)};
      const componentCSSMap = ${JSON.stringify(Object.fromEntries(this.componentCSSMap))};
      
      // Функция для получения CSS по пути
      export function getCSSByPath(filePath) {
        const normalizedPath = filePath.replace(/\\\\/g, '/');
        const entry = cssPaths.find(path => path.replace(/\\\\/g, '/').includes(normalizedPath));
        
        if (entry) {
          const startMarker = '/* ' + entry + ' */';
          const startIndex = cssContent.indexOf(startMarker) + startMarker.length;
          let endIndex = cssContent.length;
          
          // Ищем следующий маркер
          for (let i = cssPaths.indexOf(entry) + 1; i < cssPaths.length; i++) {
            const nextMarker = '/* ' + cssPaths[i] + ' */';
            const nextIndex = cssContent.indexOf(nextMarker);
            if (nextIndex !== -1) {
              endIndex = nextIndex;
              break;
            }
          }
          
          return cssContent.substring(startIndex, endIndex).trim();
        }
        return null;
      }
      
      // Получить CSS для компонента по имени
      export function getCSSForComponent(componentName) {
        const componentPaths = componentCSSMap[componentName];
        if (!componentPaths) return null;
        
        return componentPaths.map(path => getCSSByPath(path)).filter(Boolean).join('\\n');
      }
      
      // Получить весь CSS
      export function getAllCSS() {
        return cssContent;
      }
      
      // Вставить CSS в документ
      export function injectCSS() {
        if (typeof document !== 'undefined') {
          const style = document.createElement('style');
          style.textContent = cssContent;
          document.head.appendChild(style);
        }
      }
      
      // Получить список всех CSS путей
      export function getCSSPaths() {
        return cssPaths;
      }
      
      // Получить CSS для нескольких путей
      export function getMultipleCSS(paths) {
        return paths.map(path => getCSSByPath(path)).filter(Boolean).join('\\n');
      }
      
      // Получить карту компонентов
      export function getComponentCSSMap() {
        return componentCSSMap;
      }
      
      // Экспорт по умолчанию - весь CSS
      export default cssContent;
    `;
    }
}

class UniversalBundler {
    constructor() {
        this.projectRoot = process.cwd();
        this.distDir = join(this.projectRoot, 'bundle');
        this.cssBundler = new CSSBundler(this.projectRoot);
    }

    async createUniversalBundle(outputFileName = 'bundle', options = {}) {
        console.log('⚡ Creating universal bundle...');

        this.ensureDirectory(this.distDir);

        const entryPoint = join(this.projectRoot, 'src', 'index.ts');

        if (!existsSync(entryPoint)) {
            console.error('❌ Entry point not found:', entryPoint);
            process.exit(1);
        }

        console.log(`📁 Entry point: ${entryPoint}`);
        console.log(`📁 Output directory: ${this.distDir}`);

        // Находим и обрабатываем CSS файлы только если включен флаг virtual-css
        let cssPlugin = null;
        if (options.virtualCss) {
            try {
                const cssFiles = await this.cssBundler.findCSSFiles(this.projectRoot);
                console.log(`🎨 Found ${cssFiles.length} CSS files`);

                if (cssFiles.length > 0) {
                    await this.cssBundler.processCSSFiles(cssFiles);

                    // Создаем плагин для виртуального CSS модуля
                    const self = this;
                    cssPlugin = {
                        name: 'virtual-css',
                        setup(build) {
                            build.onResolve({ filter: /^virtual:css$/ }, args => {
                                return { path: 'virtual:css', namespace: 'virtual-css' };
                            });

                            build.onLoad({ filter: /^virtual:css$/, namespace: 'virtual-css' }, () => {
                                return {
                                    contents: self.cssBundler.createCSSModule(),
                                    loader: 'js'
                                };
                            });
                        }
                    };
                }
            } catch (error) {
                console.warn('⚠️ CSS processing skipped:', error.message);
            }
        } else {
            console.log('🎨 Virtual CSS disabled (use --virtual-css to enable)');
        }

        const externalDeps = this.getExternalDependencies();
        console.log(`📦 External dependencies: ${externalDeps.length > 0 ? externalDeps.join(', ') : 'none'}`);

        try {
            // Создаем промисы для каждой сборки
            const buildPromises = [];

            // ESM бандл для Node.js (всегда создается)
            const esmConfig = {
                entryPoints: [entryPoint],
                bundle: true,
                outfile: join(this.distDir, `${outputFileName}.mjs`),
                platform: 'node',
                format: 'esm',
                minify: true,
                target: 'node18',
                treeShaking: true,
                external: externalDeps,
                sourcemap: true,
                define: {
                    'process.env.NODE_ENV': '"production"'
                }
            };

            // Добавляем плагин CSS если есть CSS файлы
            if (cssPlugin) {
                esmConfig.plugins = [cssPlugin];
            }

            const esmBuild = build(esmConfig)
                .then(() => {
                    console.log(`   ✅ dist/${outputFileName}.mjs (ES Modules)`);
                })
                .catch(error => {
                    console.error(`   ❌ Failed to create ESM bundle: ${error.message}`);
                    throw error;
                });

            buildPromises.push(esmBuild);

            // CommonJS бандл для Node.js (только если не только mjs)
            if (!options.onlyMjs) {
                const cjsConfig = {
                    entryPoints: [entryPoint],
                    bundle: true,
                    outfile: join(this.distDir, `${outputFileName}.cjs`),
                    platform: 'node',
                    format: 'cjs',
                    minify: true,
                    target: 'node18',
                    treeShaking: true,
                    external: externalDeps,
                    sourcemap: true,
                    define: {
                        'process.env.NODE_ENV': '"production"'
                    }
                };

                if (cssPlugin) {
                    cjsConfig.plugins = [cssPlugin];
                }

                const cjsBuild = build(cjsConfig)
                    .then(() => {
                        console.log(`   ✅ dist/${outputFileName}.cjs (CommonJS)`);
                    })
                    .catch(error => {
                        console.error(`   ❌ Failed to create CommonJS bundle: ${error.message}`);
                        throw error;
                    });

                buildPromises.push(cjsBuild);
            }

            // Бандл для браузера (только если не только mjs)
            if (!options.onlyMjs) {
                const isBrowserCompatible = await this.isBrowserCompatible(entryPoint);
                if (isBrowserCompatible) {
                    const browserConfig = {
                        entryPoints: [entryPoint],
                        bundle: true,
                        outfile: join(this.distDir, `${outputFileName}.browser.js`),
                        platform: 'browser',
                        format: 'iife',
                        minify: true,
                        target: 'es2020',
                        treeShaking: true,
                        external: this.getBrowserExternalDependencies(externalDeps),
                        sourcemap: true,
                        globalName: this.getGlobalName(outputFileName),
                        define: {
                            'process.env.NODE_ENV': '"production"'
                        }
                    };

                    if (cssPlugin) {
                        browserConfig.plugins = [cssPlugin];
                    }

                    const browserBuild = build(browserConfig)
                        .then(() => {
                            console.log(`   ✅ dist/${outputFileName}.browser.js (Browser)`);
                        })
                        .catch(error => {
                            console.error(`   ❌ Failed to create browser bundle: ${error.message}`);
                            throw error;
                        });

                    buildPromises.push(browserBuild);
                } else {
                    console.log('   ⚠️ Browser bundle skipped - contains Node.js specific code');
                }
            }

            // Ждем завершения всех сборок
            await Promise.all(buildPromises);

            console.log('\n✅ Universal bundles created:');
            if (options.onlyMjs) {
                console.log(`   📦 dist/${outputFileName}.mjs (ES Modules only)`);
            } else {
                console.log(`   📦 dist/${outputFileName}.mjs (ES Modules)`);
                console.log(`   📦 dist/${outputFileName}.cjs (CommonJS)`);
            }

            // Генерируем файл с информацией о сборке
            this.generateBuildInfo(outputFileName, externalDeps, options);

            // Показываем статистику размера файлов
            this.showFileSizes(outputFileName, options);

        } catch (error) {
            console.error('❌ Bundle creation failed:', error);
            process.exit(1);
        }
    }

    async isBrowserCompatible(entryPoint) {
        try {
            const content = readFileSync(entryPoint, 'utf-8');

            // Проверяем наличие Node.js специфичного кода
            const nodeSpecificPatterns = [
                /require\(/,
                /import.*from\s+['"]node:/,
                /import.*from\s+['"]fs['"]/,
                /import.*from\s+['"]path['"]/,
                /import.*from\s+['"]child_process['"]/,
                /process\.env/,
                /__dirname/,
                /__filename/
            ];

            return !nodeSpecificPatterns.some(pattern => pattern.test(content));
        } catch {
            return false;
        }
    }

    getExternalDependencies() {
        const packageJsonPath = join(this.projectRoot, 'package.json');

        try {
            if (!existsSync(packageJsonPath)) {
                console.log('   ℹ️ No package.json found, using default externals');
                return this.getDefaultExternals();
            }

            const packageJsonContent = readFileSync(packageJsonPath, 'utf-8');
            const packageJson = JSON.parse(packageJsonContent);

            const allDeps = [
                ...Object.keys(packageJson.dependencies || {}),
                ...Object.keys(packageJson.devDependencies || {}),
                ...Object.keys(packageJson.peerDependencies || {})
            ];

            // Фильтруем только внешние зависимости
            const externals = allDeps.filter(dep =>
                !dep.startsWith('.') &&
                !dep.startsWith('/') &&
                !dep.startsWith('file:')
            );

            return [...externals, ...this.getNodeBuiltIns()];
        } catch (error) {
            console.warn('   ⚠️ Could not read package.json, using default externals');
            return [...this.getDefaultExternals(), ...this.getNodeBuiltIns()];
        }
    }

    getNodeBuiltIns() {
        return [
            'fs', 'path', 'os', 'child_process', 'crypto', 'http', 'https',
            'net', 'dns', 'url', 'util', 'stream', 'buffer', 'events',
            'module', 'assert', 'querystring', 'zlib', 'tls', 'cluster',
            'vm', 'perf_hooks', 'readline', 'repl', 'timers', 'string_decoder',
            'node:fs', 'node:path', 'node:os', 'node:child_process', 'node:crypto',
            'node:http', 'node:https', 'node:net', 'node:dns', 'node:url',
            'node:util', 'node:stream', 'node:buffer', 'node:events'
        ];
    }

    getDefaultExternals() {
        return ['esbuild', 'typescript', '@types/*'];
    }

    getBrowserExternalDependencies(externalDeps) {
        // Для браузера исключаем все Node.js built-in модули
        return [...externalDeps, ...this.getNodeBuiltIns()];
    }

    getGlobalName(outputFileName) {
        return outputFileName
            .split(/[-_]/)
            .map((word, index) =>
                index === 0 ? word.toLowerCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
            )
            .join('');
    }

    generateBuildInfo(outputFileName, externalDeps, options) {
        const buildInfo = {
            name: outputFileName,
            timestamp: new Date().toISOString(),
            files: {
                esm: `${outputFileName}.mjs`,
                ...(options.onlyMjs ? {} : {
                    cjs: `${outputFileName}.cjs`,
                    browser: `${outputFileName}.browser.js`
                })
            },
            build: {
                tool: 'esbuild',
                target: 'node18',
                format: options.onlyMjs ? ['esm'] : ['esm', 'cjs', 'iife'],
                minify: true,
                treeShaking: true,
                onlyMjs: options.onlyMjs || false,
                virtualCss: options.virtualCss || false
            },
            externalDependencies: externalDeps,
            node: true
        };

        writeFileSync(
            join(this.distDir, `${outputFileName}.info.json`),
            JSON.stringify(buildInfo, null, 2)
        );

        console.log(`   📄 dist/${outputFileName}.info.json (Build info)`);
    }

    showFileSizes(outputFileName, options) {
        const files = [
            `${outputFileName}.mjs`,
            ...(options.onlyMjs ? [] : [
                `${outputFileName}.cjs`,
                `${outputFileName}.browser.js`
            ]),
            `${outputFileName}.info.json`
        ];

        console.log('\n📊 File sizes:');
        let hasFiles = false;

        files.forEach(file => {
            const filePath = join(this.distDir, file);
            if (existsSync(filePath)) {
                const stats = statSync(filePath);
                const size = (stats.size / 1024).toFixed(2);
                console.log(`   ${file}: ${size} KB`);
                hasFiles = true;
            } else {
                console.log(`   ${file}: ❌ NOT FOUND`);
            }
        });

        if (!hasFiles) {
            console.log('   ⚠️ No bundle files were created');
        }
    }

    ensureDirectory(path) {
        if (!existsSync(path)) {
            mkdirSync(path, { recursive: true });
        }
    }
}

// CLI обработчик
async function main() {
    const args = process.argv.slice(2);
    let outputFileName = 'bundle';
    const options = {
        onlyMjs: false,
        virtualCss: false
    };

    // Парсим аргументы командной строки
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];

        switch (arg) {
            case '--help':
            case '-h':
                showHelp();
                return;

            case '--output':
            case '-o':
                outputFileName = args[++i] || 'bundle';
                outputFileName = outputFileName.replace(/\.[^/.]+$/, '');
                break;

            case '--name':
            case '-n':
                outputFileName = args[++i] || 'bundle';
                break;

            case '--only-mjs':
            case '--esm-only':
                options.onlyMjs = true;
                break;

            case '--virtual-css':
                options.virtualCss = true;
                break;

            case '--no-minify':
                // Можно добавить логику для отключения минификации
                break;

            default:
                if (!arg.startsWith('-')) {
                    outputFileName = arg.replace(/\.[^/.]+$/, '');
                }
                break;
        }
    }

    if (options.onlyMjs) {
        console.log('🎯 Generating ESM bundle only');
    }

    if (options.virtualCss) {
        console.log('🎨 Virtual CSS enabled');
    }

    const bundler = new UniversalBundler();
    await bundler.createUniversalBundle(outputFileName, options);
}

function showHelp() {
    console.log(`
🚀 Universal Project Bundler

Универсальный сборщик для проектов с точкой входа ./src/index.ts

ИСПОЛЬЗОВАНИЕ:
  npx bundle-all-in-one [options] [output-name]

ОПЦИИ:
  -h, --help           Показать эту справку
  -o, --output <name>  Имя выходного файла (без расширения)
  -n, --name <name>    Альтернативное указание имени
  --only-mjs           Создать только ESM бандл (.mjs)
  --esm-only           Alias для --only-mjs
  --virtual-css        Включить поддержку virtual:css модуля

ПРИМЕРЫ:
  # Сборка всех форматов
  npx bundle-all-in-one

  # Сборка только ESM формата
  npx bundle-all-in-one --only-mjs
  npx bundle-all-in-one --esm-only my-library

  # Сборка с virtual:css поддержкой
  npx bundle-all-in-one --virtual-css
  npx bundle-all-in-one -o my-app --virtual-css --esm-only

  # Сборка с указанием имени файла
  npx bundle-all-in-one my-app
  npx bundle-all-in-one --output my-library

СОЗДАВАЕМЫЕ ФАЙЛЫ:
  • dist/<name>.mjs          - ES Modules версия (Node.js)
  • dist/<name>.cjs          - CommonJS версия (Node.js) [если не --only-mjs]
  • dist/<name>.browser.js   - Browser версия [если не --only-mjs]
  • dist/<name>.info.json    - Информация о сборке

ОСОБЕННОСТИ:
  • Автоматическое определение внешних зависимостей
  • Tree shaking и минификация
  • Source maps для отладки
  • Статистика размеров файлов
  • Поддержка Node.js и браузера
  • Виртуальный модуль CSS (virtual:css) по флагу --virtual-css
    `.trim());
}

// Запуск
main().catch(console.error);

export { UniversalBundler };